def type_to_dict(typ: type) ->TypeDict:
    if is_typed_dict(typ):
        return typed_dict_to_dict(typ)

    if is_any(typ):
        return {"module": "typing", "qualname": "Any"}

    if is_generic(typ):
        # Handle generic types like List[int], Dict[str, int], etc.
        qualname = qualname_of_generic(typ)
        module = typ.__module__
        elem_types = []
        if hasattr(typ, '__args__') and typ.__args__ is not None:
