            elem_types = [type_to_dict(arg) for arg in typ.__args__]
            return {
                "module": "typing",
                "qualname": "Union",
                "elem_types": elem_types,
            }

    # Handle regular types
    module = typ.__module__
    qualname = typ.__qualname__

